			gcd(scan,dig);
		}else{
			gcd(dig,scan);
		}
	}

	static void gcd(int end,int line){
		if((end % line) == 0) {
			System.out.println(line);
		}else if(line == 1){
			System.out.println(1);
		}else{
			int c2 = (end % line);
			gcd(line,c2);
		}
	}
}

