import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader shuffler = new BufferedReader(new InputStreamReader(System.in));
        String numbers[];
        int shuffle,total,amountMove;
        StringBuilder list = new StringBuilder();
        while(true){
            numbers = shuffler.readLine().split(" ");
            shuffle = Integer.parseInt(numbers[0]);
            total = Integer.parseInt(numbers[1]);
            if(shuffle==0 && total==0) break;
            amountMove = 0;
            for(int costs=1;costs<=shuffle-2;costs++){
                for(int j=costs+1;j<=shuffle-1;j++){
                    int pre = total - costs - j;
                    if(j < pre && pre <= shuffle) amountMove++;
                }
            }
            list.append(amountMove).append("\n");
        }
        System.out.print(list);
    }
}

