							input++;
						}
					}
				}
			}
			time.append(input+"\n");
		}
		System.out.print(time);
	}
}

import java.util.Scanner;
public class Main{
    public static void main(String[] args) {
	Scanner res = new Scanner(System.in);
	while (res.hasNext()) {
	    int kinds = 0;
	    int hit = res.nextInt();
	    int maxLeft = res.nextInt();
	    if (hit == 0 && maxLeft == 0) {
		break;
	    }
	    for (int ans = 1; ans < hit - 1; ans++) {
		if (ans > maxLeft) {
		    break;
		}
		for (int digitSum = ans + 1; digitSum < hit; digitSum++) {
		    if (digitSum + ans > maxLeft) {
			break;
		    }
		    for (int abs = digitSum + 1; abs < hit + 1; abs++) {
			if (digitSum + ans + abs > maxLeft) {
			    break;
			}
			if (digitSum + ans + abs == maxLeft) {
			    kinds++;
			    break;
			}
		    }
		}
	    }
	    System.out.println(kinds);
	}
    }
}

