import static java.math.BigInteger.*;

public class Main {

	public static void main(String[] args) throws IOException {
		BufferedReader builder = new BufferedReader(new InputStreamReader(System.in));
		String store;
		while(!"0".equals(store = builder.readLine())){
			System.out.println(showResult(store));
		}
	}

	private static int showResult(String store) {
		BigInteger newCost = new BigInteger(store);
		if(newCost.compareTo(TEN) < 0){
			return Integer.parseInt(newCost.toString());
		}else{
			return Integer.parseInt(newCost.remainder(TEN).toString()) + showResult(newCost.divide(TEN).toString());
		}
	}
}

