    int maxHeight = border.nextInt(); //next(文字列), nextDouble, nextLine(1行)とか
    int minCost = 0;
    for (int totalCost = 1; totalCost <= maxHeight ; totalCost++){
      for (int j = 1; j <= maxHeight; j++){
        for (int seisu = 1; seisu <= maxHeight; seisu++){
          minCost += prime(totalCost,j,seisu);
        }
      }
    }
    System.out.println(minCost);
  }

  public static int prime(int choice, int counter, int z) {

    while (choice != counter){
      if (choice > counter){
        choice = choice-counter;
      }else{
        counter = counter -choice;
      }
    }

    while (choice != z){
      if (choice > z){
        choice = choice-z;
      }else{
        z = z -choice;
      }
    }    
    return z;
  }


}

