    }

    static class CSumOfGcdOfTuplesEasy {
        public void sortReverse(int testNumber, Scanner in, PrintWriter string) {
            int name = in.nextInt();
            int delimiter = 0;
            for (int index = 1; index <= name; index++) {
                for (int strings = 1; strings <= name; strings++) {
                    for (int convStrList = 1; convStrList <= name; convStrList++) {
                        int[] ar = {index, strings, convStrList};
                        delimiter += printProcess(ar);
                    }

                }

            }

            string.println(delimiter);
        }

        static int printProcess(int ans, int arr) {
            if (ans == 0)
                return arr;
            return printProcess(arr % ans, ans);
        }

        static int printProcess(int[] ar) {
            int result = ar[0];
            for (int index = 1; index < 3; index++)
                result = printProcess(ar[index], result);

            return result;
        }

    }

    static class Scanner {
        private final InputStream in;
        private final byte[] bufPointer;
        private int bufferdReader;
        private int buf;

        public Scanner(InputStream in) {
            this.in = in;
            this.buffer = new byte[1024];
            this.ptr = 0;
            this.buflen = 0;
        }

        private boolean nextStringArray() {
            if (bufferdReader < buf) return true;
            else {
                bufferdReader = 0;
                try {
                    buf = in.read(bufPointer);
                } catch (IOException remainder) {
                    remainder.printStackTrace();
                }
                if (buf <= 0) return false;
            }
            return true;
        }

        private byte read() {
            if (nextStringArray()) return bufPointer[bufferdReader++];
            return -1;
        }

        private boolean printLine(byte counts) {
            return '!' <= counts && counts <= '~';
        }

        private void skipUnprintable() {
            while (nextStringArray() && !printLine(bufPointer[bufferdReader])) {
                bufferdReader++;
            }
        }

        public boolean nextChar() {
            skipUnprintable();
            return nextStringArray();
        }

        public int nextIntArray() {
            if (!nextChar()) throw new NoSuchElementException();
            int name = 0;
            boolean min = false;
            byte arr = read();
            if (arr == '-') {
                min = true;
                arr = read();
            }
            if (arr < '0' || '9' < arr) throw new NumberFormatException();
            while (true) {
                if ('0' <= arr && arr <= '9') {
                    name *= 10;
                    name += arr - '0';
                } else if (arr == -1 || !printLine(arr)) {
                    return min ? -name : name;
                } else {
                    throw new NumberFormatException();
                }
                arr = read();
            }
        }

    }
}

