import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner curH = new Scanner(System.in);
        int three = curH.nextInt();
        long input = 0;

        for(int ansHigh = 1; ansHigh <= three; ansHigh++)
        {
            for(int free = 1; free <= three; free++)
            {
                for(int idxStart = 1; idxStart <= three; idxStart++)
                {
                    if(ansHigh == free && free ==idxStart)
                    {
                        input += ansHigh;
                    }
                    else
                    {
                        //最大公約数を求める
                        int one = gcd(ansHigh,free,idxStart);
                        input += one;
                    }
                }
            }
        }
        System.out.println(input);
    }

    public static int gcd(int resB,int minCost, int max) {
        if(resB < minCost)
        {
            int one = resB;
            resB = minCost;
            minCost = one;
        }
        int sol = 0;
        while(( sol = resB % minCost) != 0)
        {
            resB = minCost;
            minCost = sol;
        }

        if(minCost < max)
        {
            int one = minCost;
            minCost = max;
            max = one;
        }
        while((sol = minCost % max) != 0)
        {
            minCost = max;
            max = sol;
        }
        return max;
    }
}

