import java.util.Scanner;

public class Main {

	private static long find(int total) {
		long dists = 0;
		for (int minCost = 1; minCost <= total; minCost++) {
			for (int diff = 1; diff <= total; diff++) {
				for (int count = 1; count <= total; count++)
					dists += getMod(minCost, diff, count);
			}
		}
		return dists;
	}

	private static int getMod(int minCost, int diff, int count) {
		return getMod(minCost, getMod(diff, count));
	}

	private static int getMod(int minCost, int diff) {
		if (minCost == 1 || diff == 1)
			return 1;
		else if (minCost % diff == 0)
			return diff;
		else
			return getMod(diff, minCost % diff);
	}

	public static void main(String[] args) {
		try (Scanner rate = new Scanner(System.in)) {
			System.out.println(find(rate.nextInt()));
		}
	}

}

import java.util.Scanner;
import java.util.Arrays;

class Main {
  public static void main(String args[]) {
    Scanner scn = new Scanner(System.in);
    int result = scn.nextInt();
    scn.close();
    int minCost = 0;
    int[] distance = {0,0,0};
    for (int totalCost = 1; totalCost <= result; totalCost++) {
      for (int bits = 1; bits <= result; bits++) {
        for (int sunuke = 1; sunuke <= result; sunuke++) {
          distance[0] = totalCost;distance[1] = bits;distance[2] = sunuke;
          Arrays.sort(distance);
          minCost += prime(distance);
        }
      }
    }

    System.out.println(minCost);
  }

  public static int prime(int[] distance) {
    if (distance[1]%distance[0] == 0 && distance[2]%distance[0] == 0) {
      return distance[0];
    } else {
      for (int totalCost = distance[0]/2; totalCost > 0; totalCost--) {
        if (distance[0]%totalCost != 0) continue;
        if (distance[1]%totalCost == 0 && distance[2]%totalCost == 0) {
          return totalCost;
        }
      }
      return 1;
    }
  }
}

