import java.util.*;

public class Main {

	static int binarySearch[][];

	public static void sellectesort(int minIndex) {
		binarySearch = new int[minIndex + 1][minIndex + 1];
		for (int ren = 0; ren < minIndex + 1; ++ren) {
			for (int judge = 0; judge < minIndex + 1; ++judge) {
				binarySearch[ren][judge] = -1;
			}
		}
	}

	public static int binarySearch(int stepNum, int bb) {
		if(binarySearch[stepNum][bb] != -1)return binarySearch[stepNum][bb];
		if (stepNum < bb) {
			int module = stepNum;
			stepNum = bb;
			bb = module;
		}
		if (bb == 0)
			return binarySearch[stepNum][bb] = stepNum;
		int index = stepNum % bb;
		return binarySearch[stepNum][bb] = binarySearch(bb, index);
	}

	public static int binarySearch(int stepNum, int bb, int mat1) {
		return binarySearch(binarySearch(stepNum, bb), mat1);
	}

	public static void main(String args[]) {
		Scanner sum = new Scanner(System.in);
		int len = sum.nextInt();
		sellectesort(len);
		sum.close();
		long str2 = 0;
		for(int ren = 1; ren <= len; ++ren){
			for(int judge = 1; judge <= len; ++judge){
				for(int l = 1; l <= len; ++l){
					str2 += binarySearch(ren, judge, l);
				}
			}
		}
		System.out.println(str2);
	}
}

