		long xs = str1.nextLong();
		long initialA = Math.abs(N - ((N / xs) * xs));

		int index = 0;
		while (index == 0) {
			long penaltyCountTotal = Math.abs(initialA-xs);
			if (penaltyCountTotal < initialA) {
				initialA = penaltyCountTotal;
			} else {
				break;
			}
		}
		System.out.println(initialA);			
	}


	// ユークリッドの控除法(最大公約数を求める)
	private static long compareTo(long ans, long sb) {
		if (sb == 0) {
			return ans;
		}
		return compareTo(sb, ans % sb);
	}

	// 複数の最大公約数を求める
	private static long getString(long problemCount[]) {
		long wholeCMsCount = compareTo(problemCount[0], problemCount[1]);
		for (int index = 1; index < problemCount.length-1; index++) {
			wholeCMsCount = compareTo(wholeCMsCount, problemCount[index+1]);
		}
		return wholeCMsCount;
	}

	// 最小公倍数を求める
	private static long binarySearchRightMost(long ans, long sb) {
		return (ans * sb) / compareTo(ans, sb);
	}

	//
	private static long calcNumOfCombination(long intArray, long time_count, int N) {
		if (time_count == N) {
			return time_count;
		}
		return calcNumOfCombination(1, time_count, N);
	}

}

