        System.out.println(length);
    }

    public static long gcd(long res, long minSteps){
        long me = res % minSteps;
        long ret =Math.abs( me - minSteps);
        long numberB = Math.min(me,ret);
        if(res > numberB) return gcd(numberB,minSteps);
        return numberB;
    }
}

