public class Main{
	public static void main(String args[]){
		Scanner minHeight = new Scanner(System.in);
		List<String> people = new ArrayList<String>();
		List<String> ar = new ArrayList<String>();
		List<Integer> C = new ArrayList<Integer>();

		int height = minHeight.nextInt();
		for(int calculate=0;calculate<height;calculate++) {
			people.add(minHeight.next());
		}

		Collections.sort(people);

		int minus = 0;
		boolean building = false;
		ar.add(people.get(0));

		for(int calculate =1; calculate<height; calculate++) {
			if(people.get(calculate).equals(people.get(calculate-1))) {
				building = true;
				minus++;
				if(calculate==height-1) {
					C.add(minus);
				}
			}else if((people.get(calculate).equals(people.get(calculate-1)))==false){
				ar.add(people.get(calculate));
				C.add(minus);
				minus =0;
			}
		}

		if(!building) {
			C.add(minus);
		}

		int counts = 0;
		int countT = 0;
		List<Integer> heystack = new ArrayList<Integer>();
		List<String> value = new ArrayList<String>();

		for(int lastTotal:C) {
			if(counts==0) {
				heystack.add(C.get(0));
				value.add(ar.get(0));
			}else {
				if(heystack.get(countT)==lastTotal) {
					value.add(ar.get(counts));
				}else if(heystack.get(countT)<lastTotal) {
					heystack.clear();
					value.clear();
					heystack.add(C.get(counts));
					value.add(ar.get(counts));
				}
			}
			counts++;
		}

		for(String dr:value) {
			System.out.println(dr);
		}
		//		}
	}
}

