import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner start = new FastScanner();
        final int lenbuf = start.nextInt();
        final int result = start.nextInt();
        int instance[] = start.nextIntArray(result);
        int stack = 0;
        for (int intlist = 0; intlist < result; intlist++)
            stack += instance[intlist];
        if (stack < lenbuf)
            System.out.println("No");
        else
            System.out.println("Yes");
    }

    // FastScanner start
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] stringBuilder = new byte[1024];
        private int str = 0;
        private int bufLength = 0;

        private boolean nextStringArray() {
            if (str < bufLength) {
                return true;
            } else {
                str = 0;
                try {
                    bufLength = in.read(stringBuilder);
                } catch (IOException remainder) {
                    remainder.printStackTrace();
                }
                if (bufLength <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readD() {
            if (nextStringArray())
                return stringBuilder[str++];
            else
                return -1;
        }

        private static boolean readLineInt(int c12) {
            return 33 <= c12 && c12 <= 126;
        }

        public boolean nextByte() {
            while (nextStringArray() && !readLineInt(stringBuilder[str]))
                str++;
            return nextStringArray();
        }

        public String nextLongMap() {
            if (!nextByte())
                throw new NoSuchElementException();
            StringBuilder string = new StringBuilder();
            int b = readD();
            while (readLineInt(b)) {
                string.appendCodePoint(b);
                b = readD();
            }
            return string.toString();
        }

        public long nextLongArray() {
            if (!nextByte())
                throw new NoSuchElementException();
            long name = 0;
            boolean ints = false;
            int b = readD();
            if (b == '-') {
                ints = true;
                b = readD();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= b && b <= '9') {
                    name *= 10;
                    name += b - '0';
                } else if (b == -1 || !readLineInt(b)) {
                    return ints ? -name : name;
                } else {
                    throw new NumberFormatException();
                }
                b = readD();
            }
        }

        public int nextInt() {
            long no = nextLongArray();
            if (no < Integer.MIN_VALUE || no > Integer.MAX_VALUE)
                throw new NumberFormatException();
            return (int) no;
        }

        public double nextDouble() {
            return Double.parseDouble(nextLongMap());
        }

        public int[] nextDoubleArray(int name) {
            int arr[] = new int[name];
            for (int intlist = 0; intlist < name; intlist++) {
                arr[intlist] = nextInt();
            }
            return arr;
        }
    }
    // FastScanner end
}

