    static class FastScanner {
        public BufferedReader buffer;
        public StringTokenizer filter;

        public FastScanner(InputStream writer) {
            buffer = new BufferedReader(new InputStreamReader(writer), 32768);
            filter = null;
        }
        public boolean hasNext() {
            while (filter == null || !filter.hasMoreTokens()) {
                try {
                    filter = new StringTokenizer(buffer.readLine());
                } catch (Exception array) {
                    return false;
                }
            }
            return true;
        }

        public String nextString() {
            if (hasNext())
                return filter.nextToken();
            return null;
        }

        public String nextLine() {
            if (hasNext())
                return filter.nextToken("");
            else
                return null;
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public long nextLong() {
            return Long.parseLong(nextString());
        }

        public double nextDouble() {
            return Double.parseDouble(nextString());
        }

        public BigInteger nextBigInteger() {
            return new BigInteger(nextString());
        }

        public BigDecimal nextBigDecimal() {
            return new BigDecimal(nextString());
        }
    }
}

