//		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
//		String W	 = in.readLine();
//		int num = Integer.parseInt(W.split(" ")[0]);

		Scanner scan = new Scanner(System.in);
		int minHeight = scan.nextInt();
		String S = scan.next();
		String free = scan.next();
		String min ="";

		for(int input2 = 0;input2<minHeight; input2++) {
			min += S.charAt(input2);
			min += free.charAt(input2);
		}




		System.out.println(min);

	}

	//	//二分探索
	//k <= num となる最小の配列要素kのインデックスを返す
	static private int binarySearchRightMost(long nums, long[] strArray){
		int answer = -1;
		int reader = strArray.length;
		int minus;

		while(reader - answer >1) {
			minus = (reader + answer)/2;
			if(strArray[minus]<=nums) {
				answer = minus;
			}else {
				reader = minus;
			}
		}
		return answer;
	}

	//二分探索
	//k <= num となる最小のList要素kのインデックスを返す
	static private int binarySearchRightMost(long nums, ArrayList<Long> string){
		int answer = -1;
		int reader = string.size();
		int minus;

		while(reader - answer >1) {
			minus = (reader + answer)/2;
			if(string.get(minus)<=nums) {
				answer = minus;
			}else {
				reader = minus;
			}
		}
		return answer;
	}

	//aとbの最小公倍数を求める
	public static int prod(int acd, int bs) {
        return bs == 0 ? acd: prod(bs, acd % bs);
	}
	public static long prod(long acd, long bs) {
        return bs == 0 ? acd: prod(bs, acd % bs);
	}



}

