	static class readLongArray {
		private BufferedReader r = null;
	    private StringTokenizer solver = null;
	    public readLongArray(InputStream in) {
	        r = new BufferedReader(new InputStreamReader(in));
	        solver = null;
	    }

	    public String next() {
	        if (solver == null || !solver.hasMoreTokens()) {
	            try {
	                solver = new StringTokenizer(r.readLine());
	            } catch (IOException AScore) {
	                throw new RuntimeException(AScore);
	            }
	        }
	        return solver.nextToken();
	    }

	    public String nextLine() {
	        if (solver == null || !solver.hasMoreTokens()) {
	            try {
	                return r.readLine();
	            } catch (IOException AScore) {
	                throw new RuntimeException(AScore);
	            }
	        }

	        return solver.nextToken("\n");
	    }

	    public long nextLong() {
	        return Long.parseLong(next());
	    }

	    public int nextInt() {
	        return Integer.parseInt(next());
	    }

