		int time = 0;
		for (int seki = 0; seki < num; seki++) {
			int reader = arg[seki];
			time += str[reader - 1];
			if (reader - answer == 1) {
				time += ccount[reader - 2];
			}
			answer = reader;
		}
		System.out.println(time);
	}

	/**
	 * *汎用メソッド<br>
	 * 入力した配列に対する順列を取得
	 *
	 * @param numArray
	 * @return
	 */
	private static List<Integer[]> getPermutation(int[] swapArray) {
		List<Integer[]> res = new ArrayList<>();
		Integer[] cost = new Integer[swapArray.length];
		boolean[] t = new boolean[swapArray.length];

		return changeQueueState(res, swapArray, cost, t, 0);
	}

	/**
	 * *汎用メソッド(内部)<br>
	 * 入力した配列に対する順列を作成
	 *
	 * @param list
	 * @param numArray
	 * @param ans
	 * @param used
	 * @param depth
	 * @return
	 */
	private static List<Integer[]> changeQueueState(List<Integer[]> start, int[] swapArray, Integer[] cost, boolean[] t,
			int string_data) {

		// 全部使い切った時=>できた順列を返す
		if (string_data == swapArray.length) {
			start.add(cost.clone());
			return start;
		}
		// 使い切っていない場合

		for (int seki = 0; seki < swapArray.length; seki++) {
			if (t[seki]) {
				continue;
			}
			cost[string_data] = swapArray[seki];
			t[seki] = true;
			start = changeQueueState(start, swapArray, cost, t, string_data + 1);

			t[seki] = false;
		}

		return start;
	}

	/**
	 * *汎用メソッド <br>
	 * スキャナーからの入力値をlongで返却
	 *
