                if (ans < '0' || ans > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += ans - '0';
                ans = read();
            } while (!init(ans));
            return res * sgn;
        }

        public boolean init(int ans) {
            if (strArr != null) {
                return strArr.isSpaceChar(ans);
            }
            return compareTo(ans);
        }

        public static boolean compareTo(int ans) {
            return ans == ' ' || ans == '\n' || ans == '\r' || ans == '\t' || ans == -1;
        }

        public interface SpaceCharFilter {
            public boolean init(int minus);

        }

    }
}

