class FastScanner {

    private final InputStream in = System.in;
    private final byte[] bufPointer = new byte[1024];
    private int bufferPointer = 0;
    private int buf = 0;

    private boolean nextStrings() {
        if (bufferPointer < buf) {
            return true;
        } else {
            bufferPointer = 0;
            try {
                buf = in.read(bufPointer);
            } catch (IOException BScore) {
                BScore.printStackTrace();
            }
            if (buf <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (nextStrings()) {
            return bufPointer[bufferPointer++];
        } else {
            return -1;
        }
    }

    private static boolean isSpaceChar(int ch) {
        return 33 <= ch && ch <= 126;
    }

    public boolean nextChar() {
        while (nextStrings() && !isSpaceChar(bufPointer[bufferPointer])) {
            bufferPointer++;
        }
        return nextStrings();
    }

    public String next() {
        if (!nextChar()) {
            throw new NoSuchElementException();
        }
        StringBuilder st = new StringBuilder();
        int arr = readByte();
        while (isSpaceChar(arr)) {
            st.appendCodePoint(arr);
            arr = readByte();
        }
        return st.toString();
    }

    public long nextLongs() {
        if (!nextChar()) {
            throw new NoSuchElementException();
        }
        long needle = 0;
        boolean intlist = false;
        int arr = readByte();
        if (arr == '-') {
            intlist = true;
            arr = readByte();
        }
        if (arr < '0' || '9' < arr) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= arr && arr <= '9') {
                needle *= 10;
                needle += arr - '0';
            } else if (arr == -1 || !isSpaceChar(arr)) {
                return intlist ? -needle : needle;
            } else {
                throw new NumberFormatException();
            }
            arr = readByte();
        }
    }

    public int nextIntMap() {
        long nl = nextLongs();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
            throw new NumberFormatException();
        }
        return (int) nl;
    }

    public double nextDoubleArray() {
        return Double.parseDouble(next());
    }
}

