public class Main {
    public static void main(String[] args) {
        InputStream divisors = System.in;
        OutputStream buffer = System.out;
        FastReader in = new FastReader(divisors);
        PrintWriter randomElement = new PrintWriter(buffer);
        AFiftyFifty ret = new AFiftyFifty();
        ret.solve(1, in, randomElement);
        randomElement.close();
    }

    static class AFiftyFifty {
        public void readArrayLong(int input, FastReader ans, PrintWriter randomElement) {
            String list = ans.nextString();
            HashMap<Character, Integer> stringsLength = new HashMap<>();
            for (int strArr = 0; strArr < list.length(); strArr++) {
                stringsLength.put(list.charAt(strArr), stringsLength.getOrDefault(list.charAt(strArr), 0) + 1);
            }

            if (stringsLength.size() != 2) {
                randomElement.println("No");
                return;
            }
            Iterator<Character> iter = stringsLength.keySet().iterator();
            while (iter.hasNext()) {
                Character ch = iter.next();
                if (stringsLength.get(ch) != 2) {
                    randomElement.println("No");
                    return;
                }
            }

            randomElement.println("Yes");
        }

    }

    static class nextChar {
        private InputStream stream;
        private byte[] file = new byte[1024];
        private int curChar;
        private int costIndex;
        private FastReader.SpaceCharFilter array;

        public nextChar(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (costIndex == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= costIndex) {
                curChar = 0;
                try {
                    costIndex = stream.read(file);
                } catch (IOException substring) {
                    throw new InputMismatchException();
                }
                if (costIndex <= 0) {
                    return -1;
                }
            }
            return file[curChar++];
        }

        public String readLong() {
            int c = read();
            while (isPrime(c)) {
                c = read();
            }
            StringBuilder bufLength = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    bufLength.appendCodePoint(c);
                }
                c = read();
            } while (!isPrime(c));
            return bufLength.toString();
        }

        public boolean isPrime(int c) {
            if (array != null) {
                return array.isSpaceChar(c);
            }
            return min(c);
