public class Main {

	static Scanner module;
	static long[][] cost;
    static int current=1;
	public static void main(String[] args) {
	    module = new Scanner(System.in);

	    int n=nd();
	    int cnt=nd();
        boolean[] pre=new boolean[n+1];
        int[] str2=new int[cnt];
        cost=new long[2][n+1];
        cost[0][1]=1;
        cost[1][1]=1;
        pre[0]=true;
        pre[n]=true;

        for (int mini=0; mini<cnt;mini++) {
            str2[mini]=nd();
            pre[str2[mini]]=true;
            pre[str2[mini]-1]=true;
            pre[str2[mini]+1]=true;
            if(mini!=0 && str2[mini]-str2[mini-1] == 1) {
            	System.out.println(0);
            	return;
            }
        }

        long scan=0;
        List<Long> out = new ArrayList<Long>();
        for (int mini=0; mini<n+1;mini++) {
            if(scan!=0 && pre[mini]) {
            	out.add(scan);
            	scan=0;
            } else if(!pre[mini]) {
            	scan++;
            }
        }

        long min_number=1;
        for (int mini=0; mini<out.size();mini++) {
        	long max=out.get(mini);
        	min_number = (min_number*preCalcFactorials(max)) % 1000000007l;
        }

        System.out.println(min_number);
	}

	public static long preCalcFactorials(long v) {
		if(current>=v) {
			return (cost[0][(int)v]+cost[1][(int)v]) % 1000000007l;
		}

		for (int mini=current+1; mini<=v; mini++) {
			cost[0][mini]=cost[1][mini-1];
			cost[1][mini]=(cost[0][mini-1] +cost[1][mini-1]) % 1000000007l;
		}
		current=(int)v;
		return (cost[0][(int)v]+cost[1][(int)v]) % 1000000007l;
	}

	// a^nをmodで割ったあまり
	public static long compare(long str2, long n, long ret) {
		long strs=1;
		while(n>0) {
			if((n & 1) == 1) strs=strs*str2%ret;
			str2=str2*str2%ret;
			n=n>>1;
		}

		return strs;
	}

