        static long[] root = new long[100000 + 1];

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            Arrays.fill(root, -1);
            int stringsLength = in.readInt();
            int st = in.readInt();
            for (int set = 0; set < st; set++) {
