        }

        public long min(int index) {
            if (root[index] != -1) {
                return root[index];
            }
            if (index == 0) {
                return 0;
            }
            if (index == 1) {
                return 1;
            }
            if (index == 2) {
                if (root[1] == 0) {
                    return 1;
                }
                return 2;
            }

            root[index] = (min(index - 1) + min(index - 2)) % 1000000007;
            return root[index];
        }

    }

    static class readByte {
        private InputStream bufferdReader;
        private byte[] breakStr = new byte[1024];
        private int charlie;
        private int numChars;
