            this.stream = bufferdReader;
        }

        public int readStringsSplitByDelimiter() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (charlie >= numChars) {
                charlie = 0;
                try {
                    numChars = bufferdReader.read(breakStr);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return breakStr[charlie++];
        }

        public int readLongArray() {
            int ct = readStringsSplitByDelimiter();
            while (string(ct)) {
                ct = readStringsSplitByDelimiter();
            }
            int sgn = 1;
            if (ct == '-') {
                sgn = -1;
                ct = readStringsSplitByDelimiter();
            }
            int tle = 0;
            do {
                if (ct < '0' || ct > '9') {
                    throw new InputMismatchException();
                }
                tle *= 10;
                tle += ct - '0';
                ct = readStringsSplitByDelimiter();
            } while (!string(ct));
            return tle * sgn;
        }

        public boolean string(int ct) {
            if (filter != null) {
                return filter.isSpaceChar(ct);
            }
            return distance(ct);
        }

        public static boolean distance(int ct) {
            return ct == ' ' || ct == '\n' || ct == '\r' || ct == '\t' || ct == -1;
