public class nextLongArray
{
  final int swapCount = (int)1e9+7;
  int inputStr, st;
  boolean[] list;
  int[] Dp;

  nextLongArray(Scanner in, PrintWriter apple)
  {
	inputStr = in.nextInt();
    st = in.nextInt();
    list = new boolean[inputStr+2];
    for (int value = 0; value < st; value++)
      list[in.nextInt()] = true;
    Dp = new int[inputStr];
    Arrays.fill(Dp, -1);
    apple.println(Dp(0));
  }

  int Dp(int str)
  {
    if (str == inputStr) return 1;
    if (str > inputStr) return 0;
    if (Dp[str] != -1) return Dp[str];
    int set = 0;
    if (!list[str+1]) set += Dp(str+1);
    set %= swapCount;
    if (!list[str+2]) set += Dp(str+2);
    set %= swapCount;
    return Dp[str] = set % swapCount;
  }

