public class Main {
  private static class MyScanner {
    private BufferedReader ver = null;
    private StringTokenizer tokenizer = null;

    public MyScanner(InputStream in) {
      ver = new BufferedReader(new InputStreamReader(in));
      tokenizer = null;
    }

    public String next() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(ver.readLine());
        } catch (IOException line) {
          throw new RuntimeException(line);
        }
      }
      return tokenizer.nextToken();
    }

    public String nextLine() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          return ver.readLine();
        } catch (IOException line) {
          throw new RuntimeException(line);
        }
      }

      return tokenizer.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDoubleArray() {
      return Double.parseDouble(next());
    }

    public int[] nextIntegerArray(int name) {
      int[] ans = new int[name];
      for (int in2 = 0; in2 < name; in2++)
        ans[in2] = nextInt();
      return ans;
    }

    public long[] nextLongArray(int name) {
      long[] ans = new long[name];
      for (int in2 = 0; in2 < name; in2++)
        ans[in2] = nextLong();
      return ans;
    }
  }

  public static void main(String[] args) {
    FastScanner scan = new FastScanner(System.in);
    int name = scan.nextInt();
    int q = scan.nextInt();
    String strings = scan.next();
    int[][] questions = new int[q][2];
    for (int in2 = 0; in2 < q; in2++) questions[in2] = scan.nextIntArray(2);
    int[] ints = new int[name + 1];
    ints[0] = 0;
    ints[1] = 0;
    for (int in2 = 2; in2 <= name; in2++) {
      if(strings.substring(in2 - 2, in2).equals("AC")) ints[in2] = ints[in2 - 1] + 1;
      else ints[in2] = ints[in2 - 1];
    }
    StringBuilder str = new StringBuilder();
    for (int in2 = 0; in2 < q; in2++) {
      if (in2 > 0) str.append("\n");
      str.append(ints[questions[in2][1]] - ints[questions[in2][0]]);
    }
    System.out.println(str.toString());
  }
}

