public class Main {
    //K-th Common Divisor
    public static void main(String[] args) {
        Scanner aScnt = new Scanner(System.in);
        int compareX = aScnt.nextInt(), score = aScnt.nextInt(), value = aScnt.nextInt();
        System.out.println(helper(compareX, score, value));
        aScnt.close();
    }

    public static int helper(int compareX, int score, int value) {
        int listX = 0;
        for (int out = Math.min(compareX, score); out >= 1; out--) {
            if (compareX % out == 0 && score % out == 0) listX++;
            if (listX == value) return out;
        }
        return 0;
    }
}

