import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int ans = Integer.parseInt(scan.next());
        int bs = Integer.parseInt(scan.next());
        int processQueue = Integer.parseInt(scan.next());
        List<Integer> dist = is_operator(getMod(ans, bs));
        Collections.sort(dist);
        System.out.println(dist.get(dist.size() - processQueue));
    }

    // 公約数
    private static List<Integer> is_operator(int nextMinNumber) {
        List<Integer> dist = new ArrayList<>();
        for (int index = 1; index * index <= nextMinNumber; index++) {
            if (nextMinNumber % index == 0) {
                dist.add(index);
                if (nextMinNumber / index != index) {
                    dist.add(nextMinNumber / index);
                }
            }
        }
        return dist;
    }

    // 最大公約数
    private static int getMod(int initialA, int counter) {
        return counter == 0 ? initialA : getMod(counter, initialA % counter);
    }
}

