            while (true) {
                if (index > total_time && index > arr) break;

                if (total_time % index == 0 && arr % index == 0) costs.add(index);

                index++;
            }

            Collections.sort(costs, Collections.reverseOrder());
            // 出力
            out.println(costs.get(processQueue - 1));

        }

    }
}

