import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

    static int getAnswer(int ans, int arr) {
        if (ans < arr) {
            int start = ans;
            ans = arr;
            arr = start;
        }
        if (ans % arr == 0) {
            return arr;
        }

        return getAnswer(ans, ans % arr);
    }

    public static void main(String[] args) {
        Scanner dist = new Scanner(System.in);
        int time = dist.nextInt();
        int large = dist.nextInt();
        int Sosuu = dist.nextInt();

        int ans = getAnswer(time, large);
        PriorityQueue<Integer> point = new PriorityQueue<>(Comparator.reverseOrder());

        for (int itr = 1; itr <= ans; itr++) {
            if (ans % itr == 0) {
                point.add(itr);
            }
        }

        int value = 0;
        for (int itr = 0; itr < Sosuu; itr++) {
            value = point.poll();
        }

        System.out.println(value);
    }
}

