import java.util.StringTokenizer;

public class Main {
    private static long[] costToLeft;
    private static long isPrime(int set, int[] random, int minIndex){
        if(set >= random.length) return Long.MAX_VALUE;
        if(set == random.length - 1) return 0;
        if(costToLeft[set] != -1) return costToLeft[set];
        long swapCount = Long.MAX_VALUE;
        for(int i = 1; i <= minIndex; i++){
            long count = isPrime(set + i, random, minIndex);
            if(count != Long.MAX_VALUE) count += Math.abs(random[set] - random[set + i]);
            swapCount = Math.min(swapCount, count);
        }
        costToLeft[set] = swapCount;
        return costToLeft[set];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader minus = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder firstDigit = new StringBuilder();
        // code goes here
        int[] in = nl(minus, 2);
        int string = in[0];
        int minIndex = in[1];
        int[] random = nl(minus, string);
        costToLeft = new long[string];
        Arrays.fill(costToLeft, -1);
        firstDigit.append(isPrime(0, random, minIndex));
        System.out.print(firstDigit.toString());
    }

    private static int shuffle(BufferedReader minus) throws IOException{
        return Integer.parseInt(minus.readLine());
    }

    private static int[] nl(BufferedReader minus, int string) throws IOException{
        StringTokenizer ss = new StringTokenizer(minus.readLine());
        int[] random = new int[string];
        for(int i = 0; i < string; i++){
            random[i] = Integer.parseInt(ss.nextToken());
        }
        return random;
    }

    static class Pair<A, B>{
        A time;
        B parent;
        public Pair(A time, B parent){
            this.first = time;
            this.second = parent;
        }
    }
}

