class readLineByte {
    public BufferedReader filter;
    public StringTokenizer ver;

    public readLineByte(InputStream stream) {
        filter = new BufferedReader(new InputStreamReader(stream), 32768);
        ver = null;
    }

    public String nextIntArray() {
        while (ver == null || !ver.hasMoreTokens()) {
            try {
                ver = new StringTokenizer(filter.readLine());
            } catch (IOException name) {
                throw new RuntimeException(name);
            }
        }
        return ver.nextToken();
    }

    public int nextLine() {
        return Integer.parseInt(nextIntArray());
    }
}



