        InputReader filter = new InputReader(System.in);
        tuple = filter.nextInt();
        process = filter.nextInt();
        chars = new int[tuple];
        intlist = new Integer[tuple];
        for(int string=0;string<tuple;string++){
            chars[string] = filter.nextInt();
        }
        System.out.println(isWhitespace(0));
    }

    static int isWhitespace(int ret){
        if(ret == tuple-1){
            return 0;
        }
        if(intlist[ret]!=null){
            return intlist[ret];
        }
        int ints = Integer.MAX_VALUE;
        for(int string=1;string<=process;string++) {
            if (ret + string < tuple) {
                int remainder = Math.abs(chars[ret] - chars[ret + string]) + isWhitespace(ret + string);
                ints = Math.min(ints, remainder);
            }
        }
        intlist[ret] = ints;
        return ints;
    }
}

