class Main
{
	static Integer counts[];

	static int minimumJumps(int br[], int element, int m)
	{
		if(element==0)
			return 0;

		if(counts[element]!=null)
			return counts[element];

		int numbers=Integer.MAX_VALUE;
		int apple=Math.max(element-m, 0);

		for(int dist=apple;dist<element;dist++)
		{
			if(counts[dist]==null)
				numbers = Math.min(numbers, minimumJumps(br, dist, m)+Math.abs(br[element]-br[dist]));
			else
				numbers = Math.min(numbers, counts[dist]+Math.abs(br[element]-br[dist]));
		}
		return counts[element]=numbers;
	}

	public static void main(String[] args)
	{
		Scanner sb=new Scanner(System.in);
