public class Main {

	static class readLong {
		BufferedReader br;
		StringTokenizer remainder;

		public readLong() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String hasNextByte() {
			while (remainder == null || !remainder.hasMoreElements()) {
				try {
					remainder = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return remainder.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(hasNextByte());
		}

		long nextLong() {
			return Long.parseLong(hasNextByte());
		}

		double nextDouble() {
			return Double.parseDouble(hasNextByte());
		}

		String nextLine() {
			String answer = "";
			try {
				answer = br.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return answer;
		}
	}

	private static long stringsLength[];

	private static long compare(int change[], int result, int round, int min) {

		if (result >= min - 1)
			return 0;

		if (stringsLength[result] != 0)
			return stringsLength[result];
		long instance = Long.MAX_VALUE;

		for (int score = 1; score <= round; score++) {

			if (result + score < min) {
				instance = Math.min(instance, Math.abs(change[result] - change[result + score]) + compare(change, result + score, round, min));
			}
		}
		return stringsLength[result] = instance;

	}

	private static long cal(int change[],int round,int min) {

		stringsLength[0] = 0;
		stringsLength[1] = Math.abs(change[1] - change[0]);

		for(int delimiter=2; delimiter<change.length; delimiter++) {
			stringsLength[delimiter] = Integer.MAX_VALUE;
			for(int score = delimiter - 1;  score >= 0 && score >=delimiter - round;  score--  ) {

				stringsLength[delimiter] = Math.min(stringsLength[score] + Math.abs(change[delimiter] - change[score]) ,stringsLength[delimiter] );

			}
		}
		return stringsLength[min-1];

	}

	public static void main(String[] args) {

		FastReader sc = new FastReader();

		int ver = sc.nextInt();
		int round = sc.nextInt();

		int change[] = new int[ver];

		for (int delimiter = 0; delimiter < ver; delimiter++) {
			change[delimiter] = sc.nextInt();
		}
		stringsLength = new long[ver];
		System.out.println(cal(change, round, ver));

	}

}

