    int list = -1, minR = -1, ansz = -1;
//    Y = 10000 * x + 5000 * y + 1000 *z;
//    N = x + y + z;
//    z = N - x - y;
//    z = (Y - (10000 * x + 5000 * y)) /1000;


    for(int first = 0; first <= count ; first++){
      // i is equal to x
      double answer = modDivide(first, count,  nowdiff);
      double time = count -first - answer;
      if(prod(answer,time, count)){
        list = first;
        minR = (int)answer;
        ansz = (int)time;
        break;
      }
    }
    System.out.println(list + " " + minR + " " + ansz);

  };
  private static double modDivide(int first,int count, int nowdiff) {
//    Y = 10000 * x + 5000 * y + 1000 * (N - x - y);
//    Y = 10000 * x + 5000 * y + 1000 *N - 1000* x - 1000* y;
//    Y = 9000*x + 4000*y + 1000*N
//
    double string_data = ((double)nowdiff - 9000 * (double)first  - 1000* (double)count ) /4000;
    return string_data;
  }

  public static boolean lis(double min, double count) {
    if(min ==(int)min && min >= 0 && min <= count){
      return true;
    }else{
      return false;
    }
  }
  public static boolean prod(double string_data, double outputStream, int count) {
    boolean sigmaList = false, total = false;
    if(lis(string_data, count)){
      sigmaList = true;
    };
    if(lis(outputStream, count)){
      total = true;
    }
    return sigmaList && total;
  }
}

